// ==========================================================================
// AGRISENSA GLOBAL ERROR PARSER & DLQ CLASSIFIER
// ==========================================================================
const inputItem = $input.first()?.json || {};
const execution = inputItem.execution || {};
const workflow = inputItem.workflow || {};
const errorObj = execution.error || inputItem.error || {};

const workflowId = workflow.id || 'wf_unknown';
const workflowName = workflow.name || 'AgriSensa Unnamed Workflow';
const nodeName = errorObj.node?.name || errorObj.node || 'Unknown Node';
const errorMessage = String(errorObj.message || errorObj.description || 'No specific error message provided');
const errorStack = String(errorObj.stack || '');
const executionId = String(execution.id || ('exec_' + Date.now()));
const executionMode = execution.mode || 'webhook';
const retryCount = execution.retryOf ? 1 : 0;

// 1. Classify severity level
let severity = 'error';
const msgLower = errorMessage.toLowerCase();
if (
  msgLower.includes('timeout') ||
  msgLower.includes('econnrefused') ||
  msgLower.includes('503') ||
  msgLower.includes('502') ||
  msgLower.includes('database') ||
  msgLower.includes('fatal')
) {
  severity = 'critical';
} else if (
  msgLower.includes('rate limit') ||
  msgLower.includes('429') ||
  msgLower.includes('quota') ||
  msgLower.includes('warning')
) {
  severity = 'warning';
}

// 2. Safe string escaping for SQL insertion
const safeSql = (str) => String(str || '').replace(/'/g, "''").replace(/\\/g, "\\\\");
const cleanMessage = safeSql(errorMessage.substring(0, 1000));
const cleanStack = safeSql(errorStack.substring(0, 2000));
const cleanWorkflowName = safeSql(workflowName);
const cleanNodeName = safeSql(nodeName);
const inputDataJson = safeSql(JSON.stringify(execution.data?.resultData?.runData || {}));

// 3. Build diagnostic alert messages
const emojiIcon = severity === 'critical' ? '🔴' : (severity === 'warning' ? '🟡' : '🟠');
const timestampStr = new Date().toISOString();

const telegramAlert = emojiIcon + ' *AGRISENSA SYSTEM ALERT*\n\n' +
  '📌 *Workflow:* `' + workflowName + '`\n' +
  '⚙️ *Failed Node:* `' + nodeName + '`\n' +
  '⚠️ *Severity:* *' + severity.toUpperCase() + '*\n' +
  '🆔 *Execution ID:* `' + executionId + '`\n' +
  '⏱ *Time (UTC):* ' + timestampStr + '\n\n' +
  '📝 *Error Summary:*\n```\n' +
  errorMessage.substring(0, 400) + '\n```\n\n' +
  '💾 *Status:* Recorded to PostgreSQL `workflow_error_logs` DLQ.';

const webhookPayload = {
  event: 'WORKFLOW_EXECUTION_FAILED',
  workflow_id: workflowId,
  workflow_name: workflowName,
  execution_id: executionId,
  node_name: nodeName,
  severity: severity,
  error_message: errorMessage,
  error_stack: errorStack,
  timestamp: timestampStr
};

return [{
  json: {
    workflow_id: workflowId,
    workflow_name: workflowName,
    workflow_name_sql: cleanWorkflowName,
    execution_id: executionId,
    node_name: nodeName,
    node_name_sql: cleanNodeName,
    error_message: errorMessage,
    error_message_sql: cleanMessage,
    error_stack: errorStack,
    error_stack_sql: cleanStack,
    input_data_sql: inputDataJson,
    severity: severity,
    execution_mode: executionMode,
    retry_count: retryCount,
    telegram_alert: telegramAlert,
    webhook_payload: webhookPayload,
    timestamp: timestampStr
  }
}];
